package com.bank.party;

import java.util.logging.Logger;

// Disjoint Set Union with path compression and union by rank.
public class RelatedPartyUnionFind {

    private static final Logger log = Logger.getLogger(RelatedPartyUnionFind.class.getName());
    private final int[] parent;
    private final int[] rank;
    private int components;

    public RelatedPartyUnionFind(int n) {
        parent = new int[n];
        rank = new int[n];
        components = n;
        for (int i = 0; i < n; i++) parent[i] = i; // each account is its own cluster
    }

    // find with path compression
    public int find(int x) {
        if (parent[x] != x) parent[x] = find(parent[x]);
        return parent[x];
    }

    // union by rank; returns true if a real merge happened
    public boolean union(int a, int b) {
        int ra = find(a), rb = find(b);
        if (ra == rb) return false;              // already same cluster
        if (rank[ra] < rank[rb]) { parent[ra] = rb; }
        else if (rank[ra] > rank[rb]) { parent[rb] = ra; }
        else { parent[rb] = ra; rank[ra]++; }
        components--;
        log.info(() -> "Merged clusters; remaining=" + components);
        return true;
    }

    public boolean connected(int a, int b) { return find(a) == find(b); }
    public int componentCount() { return components; }
}
