package com.bank.party;

import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

public class UnionFindDemo {

    private static final Logger log = Logger.getLogger(UnionFindDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        log.info("National Bank of India — Related-Party Clustering (Union-Find)");
        // Index: 0=SAV2001(Rajesh) 1=CUR3001(Priya) 2=SAV2002 3=CUR3002 4=SAV2003
        RelatedPartyUnionFind uf = new RelatedPartyUnionFind(5);
        uf.union(0, 2);                 // shared device
        uf.union(1, 3);                 // shared address
        log.info("SAV2001 ~ CUR3001? " + uf.connected(0, 1)); // false
        uf.union(2, 1);                 // bridge links the two clusters
        log.info("SAV2001 ~ CUR3001? " + uf.connected(0, 1)); // true now
        log.info("Clusters remaining: " + uf.componentCount());
    }
}
